using MapEdit;
using Microsoft.Xna.Framework;
using ProjectTower.texturesheet;

namespace ProjectTower.particles.particles.hit;

public class ElementalDecay : BaseParticle
{
	public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
	{
		p.loc = loc;
		p.rotation = rotation;
		p.flags = flags;
		p.traj = traj;
		p.frame = Rand.GetRandomFloat(0.4f, 0.6f);
		p.rDir = 0f;
		switch (p.flags)
		{
		case 1:
			p.rDir = Rand.GetRandomFloat(-10f, 10f);
			p.traj.Y = Rand.GetRandomFloat(-100f, 0f);
			p.aux = Rand.GetRandomInt(5, 9);
			p.size = Rand.GetRandomFloat(0f, 4f);
			break;
		case 2:
			p.aux = Rand.GetRandomInt(0, 4);
			p.size = Rand.GetRandomFloat(0f, 4f);
			p.rotation = Rand.GetRandomFloat(0f, 6.28f);
			p.rDir = Rand.GetRandomFloat(-1f, 1f);
			break;
		case 3:
			p.aux = Rand.GetRandomInt(1, 5);
			p.size = Rand.GetRandomFloat(0f, 2f);
			p.rotation = Rand.GetRandomFloat(0f, 6.28f);
			p.rDir = Rand.GetRandomFloat(-5f, 5f);
			break;
		case 4:
			p.aux = Rand.GetRandomInt(1, 5);
			p.size = Rand.GetRandomFloat(0f, 2f);
			p.rotation = Rand.GetRandomFloat(0f, 6.28f);
			p.rDir = Rand.GetRandomFloat(-5f, 5f);
			break;
		case 5:
			p.aux = Rand.GetRandomInt(41, 50);
			p.size = Rand.GetRandomFloat(0f, 2f);
			p.rotation = Rand.GetRandomFloat(0f, 6.28f);
			p.rDir = Rand.GetRandomFloat(-1f, 1f);
			break;
		case 6:
			p.aux = Rand.GetRandomInt(41, 50);
			p.size = Rand.GetRandomFloat(0f, 2f);
			p.rotation = Rand.GetRandomFloat(0f, 6.28f);
			p.rDir = Rand.GetRandomFloat(-1f, 1f);
			break;
		}
		p.owner = owner;
		base.Init(p, loc, traj, size, rotation, flags, owner);
	}

	public override void Update(Particle p, float frameTime)
	{
		TrimFrame(p);
		p.frame -= frameTime;
		p.loc += p.traj * frameTime;
		p.rotation += p.rDir * frameTime;
		switch (p.flags)
		{
		case 1:
			p.traj.Y -= frameTime * 300f;
			break;
		case 4:
			p.traj.Y += frameTime * 300f;
			break;
		case 3:
			p.traj.Y += frameTime * 500f;
			p.traj.X += frameTime * 100f;
			break;
		}
		if (p.frame <= 0f)
		{
			p.exists = false;
		}
	}

	public override void Draw(Particle p, float brite)
	{
		switch (p.flags)
		{
		case 1:
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * 0.05f * p.size, p.rotation, 1f, 1f, 1f, p.frame * 0.5f);
			break;
		case 2:
		{
			float num = p.frame * 0.1f;
			if (num > 0.05f)
			{
				num += (num - 0.05f) * 100f;
			}
			if (p.aux < 2)
			{
				Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), 65 + p.aux % 2, new Vector2(2f, 1f) * ScrollManager.cannedDepth[0] * 0.05f * p.size, p.rotation, 1f, 1f, 1f, num);
			}
			else
			{
				Textures.tex[ParticleManager.spritesTexIdx].DrawFlipped(ScrollManager.GetScreenLoc(p.loc, 0), 65 + p.aux % 2, new Vector2(2f, 1f) * ScrollManager.cannedDepth[0] * 0.05f * p.size, p.rotation, 1f, 1f, 1f, num);
			}
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), 0, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * 0.05f * p.size, p.rotation, 1f, 1f, 1f, p.frame * 0.5f);
			break;
		}
		case 3:
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), 1, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.125f, p.rotation, 0.65f, 0.9f, 0.2f, p.frame);
			break;
		case 4:
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), 1, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.125f, p.rotation, 1f, 1f, 1f, p.frame);
			break;
		case 5:
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.35f, p.rotation, 1f, 0.9f, 0.8f, p.frame);
			break;
		case 6:
			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.35f, p.rotation, 0.8f, 1f, 0.5f, p.frame * 0.5f);
			break;
		}
	}
}

using System;
using System.Collections.Generic;
using System.Text;
using System.Threading;
using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.config;
using ProjectTower.director;
using ProjectTower.gameservices;
using ProjectTower.map;
using ProjectTower.menu;
using ProjectTower.menu.levels;
using ProjectTower.menu.levels.createCharacter;
using ProjectTower.particles;
using ProjectTower.player;
using ProjectTower.player.randomizer;
using ProjectTower.smash;
using ProjectTower.steam;

namespace ProjectTower.gamestate;

public class NewGameManager
{
	public static void NewGame(Player p)
	{
		CreateCharacter createCharacter = (CreateCharacter)p.menuMgr.menuLevel[3];
		if (p == null)
		{
			return;
		}
		GameModeMgr.SetGameModeFromPlayer(p);
		p.Reset();
		p.sessionStartTicks = DateTime.UtcNow.Ticks;
		p.stats.Reset();
		p.playerInv.Reset();
		p.respawnFrame = 0f;
		p.endGameFrame = 0f;
		p.namelessEndFrame = 0f;
		ResetWorld(p.isEnhanced);
		Vector2 loc = new Vector2(3377f, 4951f);
		Vector2 respawnLoc = new Vector2(900f, 14800f);
		int num = CharMgr.AddCharacter("hero", loc, 1, p.ID, 0);
		Character character = CharMgr.character[num];
		character.SetPlayerIdx(p.ID);
		character.hp = character.stats.GetMaxHP();
		character.mp = character.stats.GetMaxMP();
		if (GameModeMgr.IsGameEnhanced())
		{
			character.spCapDmg = 20f;
		}
		character.stamina = 0f;
		character.loc.Y = CharCols.GetGround(character.loc);
		if (p.challenge.category[2].activeChallenge == 0)
		{
			character.equipment.helm.SetAndAddToInventory(2, "", character, canDupe: false);
			character.equipment.armor.SetAndAddToInventory(2, "", character, canDupe: false);
			character.equipment.gloves.SetAndAddToInventory(2, "", character, canDupe: false);
			character.equipment.boots.SetAndAddToInventory(2, "", character, canDupe: false);
		}
		else
		{
			character.equipment.helm.SetAndAddToInventory(2, ClassCatalog.startingClass[createCharacter.startingClass].helm, character, canDupe: false);
			character.equipment.armor.SetAndAddToInventory(2, ClassCatalog.startingClass[createCharacter.startingClass].armor, character, canDupe: false);
			character.equipment.gloves.SetAndAddToInventory(2, ClassCatalog.startingClass[createCharacter.startingClass].gloves, character, canDupe: false);
			character.equipment.boots.SetAndAddToInventory(2, ClassCatalog.startingClass[createCharacter.startingClass].boots, character, canDupe: false);
		}
		for (int i = 0; i < p.stats.classUnlocks.Length; i++)
		{
			p.stats.classUnlocks[i] = ClassCatalog.startingClass[createCharacter.startingClass].startingSkill[i];
		}
		int activeChallenge = p.challenge.category[1].activeChallenge;
		if ((uint)(activeChallenge - 1) <= 1u)
		{
			switch (p.challenge.category[1].activeChallenge)
			{
			case 1:
				character.equipment.loadout[0, 0].SetAndAddToInventory(-1, "mace_pot", character, canDupe: false);
				character.equipment.loadout[1, 0].SetAndAddToInventory(-1, "mace_pot", character, canDupe: false);
				break;
			case 2:
				character.equipment.loadout[0, 0].SetAndAddToInventory(-1, "spear_oar", character, canDupe: false);
				character.equipment.loadout[1, 0].SetAndAddToInventory(-1, "spear_oar", character, canDupe: false);
				break;
			}
			character.equipment.loadout[0, 1].SetAndAddToInventory(-1, "", character, canDupe: false);
			character.equipment.loadout[1, 1].SetAndAddToInventory(-1, "", character, canDupe: false);
			character.equipment.loadout[0, 2].SetAndAddToInventory(-1, "", character, canDupe: false);
			character.equipment.loadout[1, 2].SetAndAddToInventory(-1, "", character, canDupe: false);
		}
		else
		{
			for (int j = 0; j < 2; j++)
			{
				for (int k = 0; k < 3; k++)
				{
					character.equipment.loadout[j, k].SetAndAddToInventory(-1, ClassCatalog.startingClass[createCharacter.startingClass].loadout[j, k], character, canDupe: false);
					if (k == 1 && character.equipment.loadout[j, k].catalogIdx > -1 && character.equipment.loadout[j, k].category == 0)
					{
						character.equipment.loadout[j, k].catalogIdx += 128;
					}
				}
			}
		}
		p.challenge.SetChallengeFlags();
		int num2 = 0;
		for (int l = 0; l < character.equipment.consumable.Length; l++)
		{
			character.equipment.consumable[l].SetAndAddToInventory(4, ClassCatalog.startingClass[createCharacter.startingClass].consumable[l], character, canDupe: false);
			if (ClassCatalog.startingClass[createCharacter.startingClass].consumable[l] != "")
			{
				num2 = l + 1;
			}
		}
		int num3 = 0;
		for (int m = 0; m < character.equipment.ring.Length; m++)
		{
			character.equipment.ring[m].SetAndAddToInventory(3, ClassCatalog.startingClass[createCharacter.startingClass].ring[m], character, canDupe: false);
			if (ClassCatalog.startingClass[createCharacter.startingClass].ring[m] != "")
			{
				num3 = m + 1;
			}
		}
		if (SuppliesCatalog.supplies[createCharacter.startingSupplies].loot != null)
		{
			for (int n = 0; n < SuppliesCatalog.supplies[createCharacter.startingSupplies].loot.Length; n++)
			{
				character.equipment.consumable[num2].SetAndAddToInventory(-1, SuppliesCatalog.supplies[createCharacter.startingSupplies].loot[n], character, canDupe: false);
				if (character.equipment.consumable[num2].category != 4)
				{
					if (character.equipment.consumable[num2].category == 3)
					{
						character.equipment.ring[num3].catalogIdx = character.equipment.consumable[num2].catalogIdx;
						character.equipment.ring[num3].invIdx = character.equipment.consumable[num2].invIdx;
						num3++;
					}
					character.equipment.consumable[num2].catalogIdx = -1;
					character.equipment.consumable[num2].invIdx = -1;
				}
				else
				{
					num2++;
				}
			}
		}
		for (int num4 = 0; num4 < ClassCatalog.startingClass[createCharacter.startingClass].incantation.Length; num4++)
		{
			character.equipment.incantation[num4].SetAndAddToInventory(5, ClassCatalog.startingClass[createCharacter.startingClass].incantation[num4], character, canDupe: false);
		}
		InvLoot invLoot = new InvLoot();
		invLoot.InitFromName("torch");
		p.playerInv.Add(invLoot, autoSelect: false, 1);
		character.equipment.SetTwoHandeds();
		p.stats.level = ClassCatalog.startingClass[createCharacter.startingClass].startingLevel;
		p.skinIdx = createCharacter.startingSkin;
		p.skinClass = createCharacter.startingSkinClass;
		p.hair = createCharacter.startingHair;
		p.hairColor = createCharacter.startingHairColor;
		p.beard = createCharacter.startingBeard;
		p.beardColor = createCharacter.startingBeardColor;
		p.eyeColor = createCharacter.startingEyes;
		p.name = createCharacter.name;
		p.nameStr = new StringBuilder(createCharacter.name);
		p.needsSaltStatue = false;
		p.createSaltStatueFrame = -1f;
		p.statue.exists = false;
		character.state = 0;
		character.dyingFrame = 0f;
		character.anim.SetAnimation("prayout");
		p.respawnLoc = respawnLoc;
		p.respawnLoc.Y = CharCols.GetGround(p.respawnLoc);
		p.sanctuaryRespawnLoc = p.respawnLoc;
		p.latestBossStr = "";
		p.camMgr.scroll = character.loc;
		p.zoneEnter = -1;
		p.ResetSanctuaryBonuses();
		GameStateManager.gameState = 1;
		GameStateManager.playthroughCount = p.playthroughNumber;
		GameStateManager.pvpMode = false;
		GameStateManager.newGameFrame = 1f;
		if (p.IsRandomized())
		{
			RandomizerMgr.InitNewRandomizer(p);
			RandomizerMgr.SetRandomData(p);
		}
		MapMgr.ProcessEntities();
		GameServicesMgr.Start();
		MapMgr.sanctuaryMgr.InitToPlayer(p);
		if (Monitor.TryEnter(SteamServiceMgr.flagsBuffer, 1000))
		{
			try
			{
				GlobalFlagsMgr.SetBossFlagsFromPlayer(p, SteamServiceMgr.flagsBuffer);
			}
			finally
			{
				Monitor.Exit(SteamServiceMgr.flagsBuffer);
			}
		}
		p.WriteCharSave(character);
		GameStateManager.SetWordsMode(0);
		p.playerInv.RefreshEquipped();
	}

	public static void LoadGame(Player p, int dataIdx)
	{
		if (p == null)
		{
			return;
		}
		bool isEnhanced = false;
		int activeChallenge = -1;
		int activeChallenge2 = -1;
		if (Monitor.TryEnter(Game1.charSaveList.charSaveSemaphore, 1000))
		{
			try
			{
				isEnhanced = Game1.charSaveList.charSaveChar[dataIdx].p.isEnhanced;
				activeChallenge = Game1.charSaveList.charSaveChar[dataIdx].p.challenge.category[5].activeChallenge;
				activeChallenge2 = Game1.charSaveList.charSaveChar[dataIdx].p.challenge.category[6].activeChallenge;
			}
			finally
			{
				Monitor.Exit(Game1.charSaveList.charSaveSemaphore);
			}
		}
		p.isEnhanced = isEnhanced;
		GameModeMgr.SetGameModeFromPlayer(p);
		p.sessionStartTicks = DateTime.UtcNow.Ticks;
		p.Reset();
		p.playerInv.Reset();
		p.endGameFrame = 0f;
		p.namelessEndFrame = 0f;
		ResetWorld(p.isEnhanced);
		int num = CharMgr.AddCharacter("hero", new Vector2(700f, -700f), 1, p.ID, 0);
		Character character = CharMgr.character[num];
		if (GameStateManager.demoMode)
		{
			((PaxDemoChars)p.menuMgr.menuLevel[22]).charSaveChar[dataIdx].Load(p, character.equipment);
		}
		else if (Monitor.TryEnter(Game1.charSaveList.charSaveSemaphore, 1000))
		{
			try
			{
				Game1.charSaveList.charSaveChar[dataIdx].Load(p, character.equipment);
			}
			finally
			{
				Monitor.Exit(Game1.charSaveList.charSaveSemaphore);
			}
		}
		character.SetPlayerIdx(p.ID);
		character.hp = character.stats.GetMaxHP();
		character.mp = character.stats.GetMaxMP();
		character.stamina = character.stats.GetMaxSP();
		character.loc = p.respawnLoc;
		p.fastTravelDest = p.respawnLoc;
		character.state = 0;
		character.dyingFrame = 0f;
		character.anim.SetAnimation("prayout");
		GameStateManager.gameState = 1;
		GameStateManager.playthroughCount = p.playthroughNumber;
		GameStateManager.pvpMode = false;
		GameStateManager.newGameFrame = 1f;
		if (p.IsRandomized())
		{
			RandomizerMgr.SetRandomData(p);
		}
		if (p == PlayerMgr.GetMainPlayer() && PlayerMgr.GetMainPlayer().IsRandomized())
		{
			MapMgr.reserveEntities.Clear();
		}
		MapMgr.ProcessEntities();
		GameServicesMgr.Start();
		p.challenge.ReadFlags();
		p.challenge.category[5].activeChallenge = activeChallenge;
		p.challenge.category[6].activeChallenge = activeChallenge2;
		MapMgr.SetSequenceToOn(p.flags.ToArray());
		MapMgr.map.triggerMgr.SetFromPlayer(p);
		MapMgr.sanctuaryMgr.InitFromPlayer(p);
		MapMgr.CheckSafeSanctuary(character, p);
		p.latestBossStr = "";
		p.camMgr.scroll = character.loc;
		p.zoneEnter = -1;
		p.respawnFrame = 0f;
		p.namelessEndFrame = 0f;
		p.endGameFrame = 0f;
		if (Monitor.TryEnter(SteamServiceMgr.flagsBuffer, 1000))
		{
			try
			{
				GlobalFlagsMgr.SetBossFlagsFromPlayer(p, SteamServiceMgr.flagsBuffer);
			}
			finally
			{
				Monitor.Exit(SteamServiceMgr.flagsBuffer);
			}
		}
		p.playerInv.RefreshEquipped();
		p.RepairCoopChar();
		SteamServiceMgr.OnPlayerLoad(p);
	}

	public static void AddCoopCharacter(Player p, CharSaveChar charSaveChar)
	{
		Player mainPlayer = PlayerMgr.GetMainPlayer();
		if (p == null)
		{
			return;
		}
		p.Reset();
		p.playerInv.Reset();
		int num = CharMgr.AddCharacter("hero", new Vector2(700f, -700f), 1, p.ID, 0);
		Character character = CharMgr.character[num];
		charSaveChar.Load(p, character.equipment);
		character.SetPlayerIdx(p.ID);
		character.hp = character.stats.GetMaxHP();
		character.mp = character.stats.GetMaxMP();
		character.stamina = character.stats.GetMaxSP();
		Character playerCharacter = CharMgr.GetPlayerCharacter(PlayerMgr.GetMainPlayer());
		character.loc = playerCharacter.loc;
		MapMgr.CheckSafeSanctuary(character, p);
		character.state = 0;
		character.dyingFrame = 0f;
		character.anim.SetAnimation("prayout");
		p.latestBossStr = "";
		p.camMgr.scroll = mainPlayer.camMgr.scroll;
		p.camMgr.zoom = mainPlayer.camMgr.zoom;
		p.zoneEnter = -1;
		p.respawnFrame = 0f;
		p.endGameFrame = 0f;
		p.namelessEndFrame = 0f;
		p.playerInv.RefreshEquipped();
		p.challenge.ReadFlags();
		if (!p.playerInv.HasInvItem("coop_bell"))
		{
			InvLoot invLoot = new InvLoot();
			invLoot.InitFromName("coop_bell");
			int num2 = p.playerInv.Add(invLoot, autoSelect: false, 1);
			if (p.pickup == null)
			{
				p.pickup = new List<Player.PlayerPickup>();
				p.pickupFrame = 3f;
			}
			if (num2 > -1)
			{
				p.AddPickup(num2, invLoot.category, invLoot.catalogIdx, 1);
			}
		}
	}

	public static void ResetWorld(bool isEnhanced = false)
	{
		ParticleManager.Reset();
		CharMgr.Reset();
		SmashMgr.Reset();
