namespace ProjectTower.physics;

public class Mass
{
	public float m;

	public Vector2 pos;

	public Vector2 vel;

	public Vector2 force;

	public Mass(float m)
	{
		this.m = m;
	}

	public void ApplyForce(Vector2 force)
	{
		if (float.IsNaN(force.X) || float.IsNaN(force.Y))
		{
			force = default;
		}
		this.force += force;
	}

	public void Init()
	{
		force.X = 0f;
		force.Y = 0f;
	}

	public void Simulate(float dt)
	{
		if (float.IsNaN(vel.X))
		{
			vel.X = 0f;
		}
		if (float.IsNaN(vel.Y))
		{
			vel.Y = 0f;
		}
		vel += force / m * dt;
		pos += vel * dt;
		if (float.IsNaN(vel.X))
		{
			vel.X = 0f;
		}
		if (float.IsNaN(vel.Y))
		{
			vel.Y = 0f;
		}
	}
}
namespace ProjectTower.physics;

public class Simulation
{
	public int numOfMasses;

	public Mass[] masses;

	public Simulation(int numOfMasses, float m)
	{
		this.numOfMasses = numOfMasses;
		masses = new Mass[numOfMasses];
		for (int i = 0; i < numOfMasses; i++)
		{
			masses[i] = new Mass(m);
		}
	}

	public virtual void Release()
	{
		masses = null;
	}

	public Mass GetMass(int index)
	{
		if (index < 0 || index >= numOfMasses)
		{
			return null;
		}
		return masses[index];
	}

	public virtual void Init()
	{
		for (int i = 0; i < numOfMasses; i++)
		{
			masses[i].Init();
		}
	}

	public virtual void Solve()
	{
	}

	public virtual void Simulate(float dt)
	{
		for (int i = 0; i < numOfMasses; i++)
		{
			masses[i].Simulate(dt);
		}
	}

	public virtual void Operate(float dt)
	{
		Init();
		Solve();
		Simulate(dt);
	}
}
