namespace ProjectTower.physics;

public class Spring
{
	private Mass mass1;

	private Mass mass2;

	public float springConstant;

	public float springLength;

	public float frictionConstant;

	public Spring(Mass mass1, Mass mass2, float springConstant, float springLength, float frictionConstant)
	{
		this.springConstant = springConstant;
		this.springLength = springLength;
		this.frictionConstant = frictionConstant;
		this.mass1 = mass1;
		this.mass2 = mass2;
	}

	public void Solve()
	{
		if (float.IsNaN(mass2.pos.X))
		{
			mass2.pos.X = mass1.pos.X;
		}
		if (float.IsNaN(mass2.pos.Y))
		{
			mass2.pos.Y = mass1.pos.Y;
		}
		if (float.IsNaN(mass1.vel.X))
		{
			mass1.vel.X = 0f;
		}
		if (float.IsNaN(mass2.vel.X))
		{
			mass2.vel.X = 0f;
		}
		if (float.IsNaN(mass1.vel.Y))
		{
			mass1.vel.Y = 0f;
		}
		if (float.IsNaN(mass2.vel.Y))
		{
			mass2.vel.Y = 0f;
		}
		Vector2 vector = mass1.pos - mass2.pos;
		float num = vector.Length();
		if (num > 100f)
		{
			num = 100f;
		}
		Vector2 vector2 = default;
		if (num > springLength && num != 0f)
		{
			vector2 += vector / num * (num - springLength) * (0f - springConstant);
		}
		vector2 += -(mass1.vel - mass2.vel) * frictionConstant;
		mass1.ApplyForce(vector2);
		mass2.ApplyForce(-vector2);
		if (mass2.pos.Y < mass1.pos.Y && mass2.force.Y < 0f)
		{
			mass2.force.Y = 1f;
		}
	}
}
