public class RopeSimulation : Simulation
{
	public Spring[] springs;

	private Vector2 gravitation;

	public Vector2 ropeConnectionPos;

	public Vector2 ropeConnectionVel;

	private float groundRepulsionConstant;

	private float groundFrictionConstant;

	private float groundAbsorptionConstant;

	private float groundHeight;

	private float airFrictionConstant;

	public RopeSimulation(int numOfMasses, float m, float springConstant, float springLength, float springFrictionConstant, Vector2 gravitation, float airFrictionConstant, float groundRepulsionConstant, float groundFrictionConstant, float groundAbsorptionConstant, float groundHeight)
		: base(numOfMasses, m)
	{
		this.gravitation = gravitation;
		this.airFrictionConstant = airFrictionConstant;
		this.groundFrictionConstant = groundFrictionConstant;
		this.groundRepulsionConstant = groundRepulsionConstant;
		this.groundAbsorptionConstant = groundAbsorptionConstant;
		this.groundHeight = groundHeight;
		for (int i = 0; i < numOfMasses; i++)
		{
			masses[i].pos.X = (float)i * springLength;
			masses[i].pos.Y = 0f;
		}
		springs = new Spring[numOfMasses - 1];
		for (int j = 0; j < numOfMasses - 1; j++)
		{
			springs[j] = new Spring(masses[j], masses[j + 1], springConstant, springLength, springFrictionConstant);
		}
	}

	public override void Solve()
	{
		for (int i = 0; i < numOfMasses - 1; i++)
		{
			springs[i].Solve();
		}
		for (int j = 0; j < numOfMasses; j++)
		{
			masses[j].ApplyForce(GameStateManager.simulationGravity * masses[j].m);
			masses[j].ApplyForce(-masses[j].vel * airFrictionConstant);
			_ = masses[j].pos.Y;
			_ = groundHeight;
		}
	}

	public override void Simulate(float dt)
	{
		base.Simulate(dt);
		ropeConnectionPos += ropeConnectionVel * dt;
		_ = ropeConnectionPos.Y;
		_ = groundHeight;
		masses[0].pos = ropeConnectionPos;
		masses[0].vel = ropeConnectionVel;
	}

	public RopeSimulation Copy()
	{
		RopeSimulation ropeSimulation = new RopeSimulation(numOfMasses, 0f, 0f, 0f, 0f, default, 0f, 0f, 0f, 0f, 0f);
		ropeSimulation.airFrictionConstant = airFrictionConstant;
		ropeSimulation.gravitation = gravitation;
		ropeSimulation.groundAbsorptionConstant = groundAbsorptionConstant;
		ropeSimulation.groundFrictionConstant = groundFrictionConstant;
		ropeSimulation.groundHeight = groundHeight;
		ropeSimulation.groundRepulsionConstant = groundRepulsionConstant;
		for (int i = 0; i < ropeSimulation.masses.Length; i++)
		{
			ropeSimulation.masses[i].force = masses[i].force;
			ropeSimulation.masses[i].m = masses[i].m;
			ropeSimulation.masses[i].pos = masses[i].pos;
			ropeSimulation.masses[i].vel = masses[i].vel;
		}
		for (int j = 0; j < ropeSimulation.springs.Length; j++)
		{
			ropeSimulation.springs[j].frictionConstant = springs[j].frictionConstant;
			ropeSimulation.springs[j].springConstant = springs[j].springConstant;
			ropeSimulation.springs[j].springLength = springs[j].springLength;
		}
		ropeSimulation.numOfMasses = numOfMasses;
		ropeSimulation.ropeConnectionPos = ropeConnectionPos;
		ropeSimulation.ropeConnectionVel = ropeConnectionVel;
		return ropeSimulation;
	}
}
