	{
		scalar = 0.002f;
		rope.ropeConnectionPos = loc * scalar;
		if ((rope.masses[0].pos - rope.ropeConnectionPos).LengthSquared() > 1f)
		{
			for (int i = 0; i < rope.masses.Length; i++)
			{
				rope.masses[i].pos = rope.ropeConnectionPos;
			}
		}
		updateTime = frameTime;
		if (!(updateTime <= 0f))
		{
			float num = updateTime;
			updateTime = 0f;
			float num2 = 0.008f;
			int num3 = (int)(num / num2) + 1;
			if (num3 != 0)
			{
				num /= (float)num3;
			}
			for (int j = 0; j < num3; j++)
			{
				rope.Operate(num);
			}
		}
	}

